<?php
if(PHP_SAPI!=='cli')exit;require __DIR__.'/../core/init.php';session_save_path(sys_get_temp_dir());session_start();$u=sc_query('SELECT userid FROM users WHERE user_group=1 AND is_active=1 AND is_deleted=0 LIMIT 1')->get_result()->fetch_assoc();$_SESSION[USER_AUTH]=$u['userid'];$csrf=sc_csrf();$tag='SC test '.bin2hex(random_bytes(4));$task=0;$ticket=0;$auditIds=[];$key='footer_heading';$original=sc_query('SELECT id,value FROM systemv WHERE variable=?','s',[$key])->get_result()->fetch_all(MYSQLI_ASSOC);$settingChanged=false;
function mverify($v,$label){if(!$v)throw new RuntimeException($label);echo 'PASS '.$label."\n";}
try{
sc_task_action(['csrf'=>$csrf,'task_action'=>'add','title'=>$tag,'due_date'=>'2027-01-01']);$task=(int)sc_query('SELECT id FROM admin_tasks WHERE title=? AND user_id=?','si',[$tag,(int)userVariable('id')])->get_result()->fetch_assoc()['id'];mverify($task>0,'follow-up saved');sc_task_action(['csrf'=>$csrf,'task_action'=>'complete','task_id'=>$task]);mverify((int)sc_query('SELECT is_done FROM admin_tasks WHERE id=?','i',[$task])->get_result()->fetch_assoc()['is_done']===1,'follow-up completed');$messages=['[admin] followup.created | record '.$task,'[admin] followup.completed | record '.$task];foreach($messages as $message)mverify((int)sc_query('SELECT COUNT(*) n FROM admin_updates WHERE update_text=? AND updated_by=?','ss',[$message,$u['userid']])->get_result()->fetch_assoc()['n']===1,'follow-up action audited once');
$ticket=sc_support_submit(['csrf'=>$csrf,'action'=>'create','title'=>$tag,'description'=>'Temporary support fixture','issue_type'=>'Other']);mverify((bool)sc_support_ticket($ticket),'support ticket creation');sc_support_submit(['csrf'=>$csrf,'action'=>'reply','ticket_id'=>$ticket,'description'=>'Test reply']);mverify((int)sc_query('SELECT COUNT(*) n FROM support_tickets WHERE reply_to_id=?','i',[$ticket])->get_result()->fetch_assoc()['n']===1,'support reply linked to root');sc_support_submit(['csrf'=>$csrf,'action'=>'resolve','ticket_id'=>$ticket]);mverify(sc_support_ticket($ticket)['status']==='Resolved','support resolution');sc_support_submit(['csrf'=>$csrf,'action'=>'reopen','ticket_id'=>$ticket]);mverify(sc_support_ticket($ticket)['status']==='Pending','support reopening');$rejected=false;try{sc_support_submit(['csrf'=>'invalid','action'=>'create','title'=>$tag,'description'=>'test']);}catch(RuntimeException $e){$rejected=true;}mverify($rejected,'support CSRF rejected');
sc_save_public_settings(['footer_heading'=>$tag],['footer_heading']);$settingChanged=true;$auditIds[]=sc_db()->insert_id;mverify(sc_query('SELECT value FROM systemv WHERE variable=? LIMIT 1','s',[$key])->get_result()->fetch_assoc()['value']===$tag,'footer setting saved');$html=file_get_contents('http://localhost/stepcure/');mverify(str_contains($html,$tag),'custom footer shown on homepage');$rejected=false;try{sc_save_public_settings(['website_instagram'=>'javascript:alert(1)'],['website_instagram']);}catch(RuntimeException $e){$rejected=true;}mverify($rejected,'unsafe social URL rejected');mverify(!str_contains(loadAdminTitleAndFavicon('Test'),'assets/img/favicon')&&str_contains(loadAdminTitleAndFavicon('Test'),'data:,'),'admin favicon cleared');
}finally{if($task){sc_query('DELETE FROM admin_tasks WHERE id=? AND title=?','is',[$task,$tag]);foreach(['followup.created','followup.completed'] as $event)sc_query('DELETE FROM admin_updates WHERE update_text=? AND updated_by=?','ss',['[admin] '.$event.' | record '.$task,$u['userid']]);}if($ticket){sc_query('DELETE FROM support_tickets WHERE id=? OR reply_to_id=?','ii',[$ticket,$ticket]);foreach(['create','reply','resolve','reopen'] as $event)sc_query('DELETE FROM admin_updates WHERE update_text=? AND updated_by=?','ss',['[admin] support.'.$event.' | record '.$ticket,$u['userid']]);}if($settingChanged){if($original){foreach($original as $row)sc_query('UPDATE systemv SET value=? WHERE id=? AND value=?','sis',[$row['value'],$row['id'],$tag]);}else sc_query('DELETE FROM systemv WHERE variable=? AND value=?','ss',[$key,$tag]);}foreach($auditIds as $id)sc_query('DELETE FROM admin_updates WHERE id=? AND update_text=?','is',[$id,'[admin] website_settings.saved']);session_destroy();echo "Temporary maintenance fixtures removed.\n";}
